using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1️⃣  GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2️⃣  TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {info!.Type.Name}");
}

// Source-gen-only options — no reflection resolver, so unknown types won't resolve
var strict = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver() // knows about common types
};
// WidgetContext only exposes Widget, not Person
strict.TypeInfoResolver = WidgetContext.Default;

if (strict.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("Person resolved (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> returned false — no metadata available");
}

// Records used in the demo
public record Person(string Name, int Age);
public record Widget(string Label);

[JsonSerializable(typeof(Widget))]
public partial class WidgetContext : JsonSerializerContext;

